function backtestInterpretation(run:BacktestRun){if(run.phase.startsWith("3.13")){const s=run.summary,t=s?.target,e=s?.economics;return "TRIM 후 gap 0~5% 날짜 신호 "+(t?.dateSignals??"—")+"건은 독립 episode "+(t?.episodes??"—")+"개로 정리됐습니다. 이 중 유효 episode는 "+(e?.find((x:any)=>x.label==="유효")?.count??"—")+"개, 낮은 효율은 "+(e?.find((x:any)=>x.label==="낮은 효율")?.count??"—")+"개, 실패는 0개였습니다. 3~5% gap은 22개 episode 중 21개가 진입·목표도달했고 중앙수익률은 약 4.7%였습니다. 3.9~3.13을 종합하면 TRIM은 폭을 줄이고 Fixed 성과와 gap을 유지했으므로 운영 적용을 권장합니다. 이번 배포에서는 운영 규칙 자체는 바꾸지 않았습니다."}if(run.phase.startsWith("3.12")){const s=run.summary,b=s?.gap?.base,t=s?.gap?.trim,a=s?.trimApplied;return "TRIM 적용 후 전체 평균 매수↔차익 gap은 "+fmt(b?.mean??null,"percent")+"에서 "+fmt(t?.mean??null,"percent")+"로 넓어졌습니다. 특히 실제 TRIM 적용 "+(a?.count??"—")+"건에서는 평균 gap이 "+fmt(a?.baseGap??null,"percent")+"에서 "+fmt(a?.trimGap??null,"percent")+"로 증가했고, 악화 사례는 없었습니다. 전체 0~5% 애매 구간은 "+fmt(b?.near5??null,"percent")+"에서 "+fmt(t?.near5??null,"percent")+"로 소폭 감소했습니다. Fixed 거래 성과는 14건·중앙수익률 22.31%로 유지됐지만, 애매 구간 표본이 매우 적어 운영 자동 반영은 보류합니다."}if(run.phase.startsWith("3.11")){const s=run.summary,b=s?.distribution?.base,t=s?.distribution?.trim,p=s?.performance;return "TRIM 적용 후 평균 매수 가격대 폭은 "+fmt(b?.meanWidth??null,"percent")+"에서 "+fmt(t?.meanWidth??null,"percent")+"로 줄었고, 폭 5% 이상 비율도 "+fmt(b?.over5??null,"percent")+"에서 "+fmt(t?.over5??null,"percent")+"로 낮아졌습니다. 다만 이 MA 방향성 표본에서는 BASE와 TRIM 모두 매수·차익 가격대 중첩이 0건이라 중첩 해소 효과는 판단할 수 없습니다. Fixed 거래는 각각 "+(p?.base?.entries??"—")+"건·"+(p?.trim?.entries??"—")+"건으로 같고 중앙수익률도 "+fmt(p?.base?.medianReturn??null,"percent")+"로 유지됐습니다. 3.10차의 29개 날짜 신호는 7개 독립 episode로 묶였으므로, 자동 제거를 운영에 반영하기에는 표본이 아직 부족합니다."}if(run.phase.startsWith('3.10')){const s=run.summary,w=s?.widthCompare,e=s?.entries;return `외딴 후보를 제거하면 평균 가격대 폭은 ${fmt(w?.originalMean??null,'percent')}에서 ${fmt(w?.trimmedMean??null,'percent')}로 줄었고, midpoint 중앙 변화는 ${fmt(w?.midpointMedian??null,'percent')}였습니다. 전체 ${s?.target?.toLocaleString()??'—'}개 사례 중 제거 시에만 놓친 진입은 ${e?.originalOnly??'—'}건입니다. 이 사례들은 인접 날짜의 유사 신호가 겹칠 수 있으므로 운영 자동 제거 근거로는 아직 부족합니다.`}if(run.phase.startsWith('3.9')){const s=run.summary;return `전체 ${s?.totalZones?.toLocaleString()??'—'}개 매수 가격대 중 폭 5% 이상은 ${fmt(s?.wide?.ratio??null,'percent')}였습니다. 넓은 사례에서 ATR cap 도달 비율은 ${fmt(s?.atrSummary?.wideCapHitRatio??null,'percent')}에 그쳐, 주원인은 cap보다 멀리 떨어진 후보 조합으로 나타났습니다. 외딴 후보 1개를 진단상 제외하면 평균 폭은 ${fmt(s?.outlierReduction?.meanBefore??null,'percent')}에서 ${fmt(s?.outlierReduction?.meanAfter??null,'percent')}로 줄었습니다.`}if(run.phase.startsWith('3.8')){const a=run.summary.range,b=run.summary.p15,c=run.summary.p20;return `MA 방향성 적용 상태에서 min~max 매수 가격대 중앙 폭은 ${fmt(a?.buyMedianWidth??null,'percent')}입니다. 대표가격 ±1.5%와 ±2.0%는 각각 ${fmt(b?.buyMedianWidth??null,'percent')}, ${fmt(c?.buyMedianWidth??null,'percent')}로 오히려 넓어졌습니다. 세 방식 모두 중첩률은 1% 이하였지만, 현재 표본에서는 min~max가 가장 좁은 기준입니다.`}if(run.phase.startsWith('3.7')){const b=run.summary.baseline,d=run.summary.directional;return `MA 방향성 적용 후 매수 가격대 중앙 폭은 ${fmt(b?.buyMedianWidth??null,'percent')}에서 ${fmt(d?.buyMedianWidth??null,'percent')}로, 매수·매도 가격대 중첩률은 ${fmt(b?.overlapRate??null,'percent')}에서 ${fmt(d?.overlapRate??null,'percent')}로 줄었습니다. 다만 완결 거래 표본은 11건과 9건이고 평균 MAE는 악화되어, 구조 개선과 운용성과의 균형은 다음 검증에서 더 확인해야 합니다.`}if(run.phase.startsWith('3.5')){const b=run.summary.baseline,d=run.summary.directional?.[1];return `기준 8% cap의 매수 가격대 중앙 폭은 ${fmt(b?.buyMedianWidth??null,'percent')}이고, MA 방향성 적용 시 ${fmt(d?.buyMedianWidth??null,'percent')}로 줄었습니다. 매수·매도 가격대 중첩률은 ${fmt(b?.overlapRate??null,'percent')}에서 ${fmt(d?.overlapRate??null,'percent')}로 낮아졌지만, 운용성과까지 함께 개선됐는지는 추가 검증이 필요합니다.`}if(run.phase.startsWith('2차')){const s=run.summary.fixed;return `고정 목표가 방식은 완결 ${s?.closed??'—'}건, 목표 도달률 ${fmt(s?.arrivalRate??null,'percent')}, 거래당 중앙수익률 ${fmt(s?.medianReturn??null,'percent')}로 계산됐습니다. 거래비용은 매수·매도 각각 0.05%를 반영했고, 이 결과만으로 운영 규칙을 자동 변경하지 않습니다.`}if(run.phase.startsWith('1.7')){const h=run.summary.horizons?.find((x:any)=>x.horizon==='60D');return `60거래일 기준 일반 표본은 ${fmt(h?.general?.median??null,'percent')}, 복합조건은 ${fmt(h?.combo?.median??null,'percent')}였습니다. 복합조건 표본은 ${h?.combo?.count?.toLocaleString()??'—'}건이며, 결과가 높아도 단기 하락 가능성까지 사라지는 것은 아닙니다.`}if(run.phase.startsWith('1.5')){const model=run.summary.models?.find((x:any)=>x.name==='현재 30/20/15');const mdd=run.summary.ablations?.find((x:any)=>x.name==='MDD 제외');return `현재 배점 모델의 고점수 60일 중앙값은 ${fmt(model?.high?.median??null,'percent')}였습니다. MDD를 제외하면 ${fmt(mdd?.high?.median??null,'percent')}로 낮아져, 낙폭과 MDD 정보가 결과 구분에 기여했을 가능성을 보여줍니다.`}const c=run.summary.conditions?.find((x:any)=>x.label==='복합 · 도달 + 70 이상');const g=run.summary.conditions?.find((x:any)=>x.label==='일반 평가 가능 거래일');return `60거래일 기준 일반 평가는 ${fmt(g?.results?.[60]?.median??null,'percent')}, 핵심가격 도달과 점수 70 이상을 함께 만족한 조건은 ${fmt(c?.results?.[60]?.median??null,'percent')}였습니다. 복합조건은 참고용 과거 비교이며 미래 수익을 보장하지 않습니다.`}
